-- M-14 1차 : 인덱스 관리 (docs/index-management-m14.md)
--  1) 인덱스 출처(IDX_SRC_CD)·파생 컬럼(DRVN_COL_SN) : 컬럼의 인덱스 여부(IDX_YN)를 TB_TBL_IDX 의 출처 COLUMN 인덱스로 옮긴다 (D-19)
--  2) 승인된 인덱스의 변경 요청 TB_IDX_CHG_DMND (D-20)
--  3) 기존 데이터 이관 : 예전 DDL 규칙(IDX_YN 이고 PK·고유값이 아님, 같은 컬럼 하나의 일반 인덱스가 이미 있으면 그것을 쓴다)과 같은 조건
--  4) 예제 (데이터 사전 → 물리 → 논리 → 매핑)
-- 이미 적용된 V0·V1·V2 는 고치지 않는다.

alter table TB_TBL_IDX add column IDX_SRC_CD varchar(20) default 'USER' not null;
alter table TB_TBL_IDX alter column IDX_SRC_CD drop default;
alter table TB_TBL_IDX add column DRVN_COL_SN bigint;
create unique index UX_TBL_IDX_01 on TB_TBL_IDX (DRVN_COL_SN);

create sequence SQ_IDX_CHG_DMND start with 1 increment by 50;
-- DMND_STTS_CD : REQUESTED / APPROVED / REJECTED, 요청자·요청 일시 = RGTR_ID·REG_DT, 처리자·처리 일시 = MDFR_ID·MDFCN_DT
create table TB_IDX_CHG_DMND (
    IDX_CHG_DMND_SN bigint not null,
    PRJ_SN bigint not null,
    IDX_SN bigint not null,
    CHG_BFR_CN TEXT not null,
    CHG_AFTR_CN TEXT not null,
    DMND_STTS_CD varchar(20) not null,
    REG_DT timestamp(6),
    MDFCN_DT timestamp(6),
    RGTR_ID varchar(255),
    MDFR_ID varchar(255),
    constraint PK_IDX_CHG_DMND primary key (IDX_CHG_DMND_SN)
);
create index IX_IDX_CHG_DMND_01 on TB_IDX_CHG_DMND (IDX_SN, DMND_STTS_CD);
alter table TB_IDX_CHG_DMND add constraint FK_IDX_CHG_DMND_01 foreign key (IDX_SN) references TB_TBL_IDX on delete cascade;

comment on column TB_TBL_IDX.IDX_SRC_CD is '인덱스 출처 코드';
comment on column TB_TBL_IDX.DRVN_COL_SN is '파생 컬럼 일련번호';
comment on table TB_IDX_CHG_DMND is '인덱스 변경 요청';
comment on column TB_IDX_CHG_DMND.IDX_CHG_DMND_SN is '인덱스 변경 요청 일련번호';
comment on column TB_IDX_CHG_DMND.PRJ_SN is '프로젝트 일련번호';
comment on column TB_IDX_CHG_DMND.IDX_SN is '인덱스 일련번호';
comment on column TB_IDX_CHG_DMND.CHG_BFR_CN is '변경 이전 내용';
comment on column TB_IDX_CHG_DMND.CHG_AFTR_CN is '변경 이후 내용';
comment on column TB_IDX_CHG_DMND.DMND_STTS_CD is '요청 상태 코드';
comment on column TB_IDX_CHG_DMND.REG_DT is '등록 일시';
comment on column TB_IDX_CHG_DMND.MDFCN_DT is '수정 일시';
comment on column TB_IDX_CHG_DMND.RGTR_ID is '등록자 아이디';
comment on column TB_IDX_CHG_DMND.MDFR_ID is '수정자 아이디';

-- ---------- 기존 데이터 이관 : 컬럼의 인덱스 여부 → 출처 COLUMN 인덱스 (모든 프로젝트) ----------
-- 이름·승인 상태는 동기화(PhysicalModelServiceImpl.syncColumnIndexes)와 같다 : IX_<테이블명>_<컬럼명>, 컬럼의 승인 여부.
-- 컬럼의 IDX_YN 값은 그대로 둔다 (컬럼 관리·엑셀의 입력값). 같은 컬럼 하나의 일반 인덱스가 이미 있으면 새로 만들지 않는다 (예전 DDL 도 한 번만 냈다).
insert into TB_TBL_IDX(IDX_SN, PRJ_SN, TBL_SN, IDX_NM, IDX_TYPE_NM, UNQ_YN, APRV_YN, IDX_SRC_CD, DRVN_COL_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID)
select nextval('SQ_TBL_IDX'), c.PRJ_SN, c.TBL_SN, 'IX_' || t.TBL_NM || '_' || c.COL_NM, null, false, coalesce(c.APRV_YN, false), 'COLUMN', c.COL_SN, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM'
from TB_COL c
join TB_TBL t on t.TBL_SN = c.TBL_SN
where c.IDX_YN = true and coalesce(c.PK_YN, false) = false and coalesce(c.UNQ_YN, false) = false
  and not exists (select 1 from TB_TBL_IDX i where i.TBL_SN = c.TBL_SN and i.UNQ_YN = false
                  and (select count(*) from TB_TBL_IDX_COL x where x.IDX_SN = i.IDX_SN) = 1
                  and exists (select 1 from TB_TBL_IDX_COL x where x.IDX_SN = i.IDX_SN and x.COL_SN = c.COL_SN));
insert into TB_TBL_IDX_COL(IDX_COL_SN, IDX_SN, COL_SN, COL_ORD)
select nextval('SQ_TBL_IDX_COL'), i.IDX_SN, i.DRVN_COL_SN, 1 from TB_TBL_IDX i where i.IDX_SRC_CD = 'COLUMN';

